  data=json.loads(p.stdout);retained=json.loads((R/'eval/qualification/e02-compensation-v1/inventory.json').read_text());row['full_inventory_equal']=data==retained;row['candidate_slot_checks']=len(data['candidate_slot_checks']);row['compensations_available']=data['compensations_available_in_frozen_scope'];assert row['full_inventory_equal']
