 assert p.returncode==0
 checks.append(row)
after=hashes();assert before==after
out={'scope':'data-only E02 inventory and own adversarial tests; no upstream/native/provider/network','review_start_head':'bc874f4','head_observed':subprocess.check_output(['git','rev-parse','HEAD'],cwd=R,text=True).strip(),'source_sha256':before,'unchanged_during_verification':before==after,'checks':checks,'passed':True,'reproducer_source':Path(__file__).read_text()}
